import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    A,B,T=map(int,data.split());q=collections.deque([(0,0,0)]);seen={(0,0)}
    while q:
        x,y,d=q.popleft()
        if x==T or y==T:return d
        p=min(x,B-y);r=min(y,A-x)
        for u,v in [(A,y),(x,B),(0,y),(x,0),(x-p,y+p),(x+r,y-r)]:
            if (u,v) not in seen:seen.add((u,v));q.append((u,v,d+1))
    return -1

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
